#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    ll n, m; cin >> n >> m;
    ll ans = (m * (m - 1) / 2);
    vector<ll> cnt(n, 0);
    for(int i = 0; i < m; i ++) {
        ll a, b; cin >> a >> b;
        a --; b --;
        if (a == (n - b)) {
            ans -= cnt[0];
            cnt[0] ++;
        } else if (a < (n - b)) {
            ans -= cnt[a + b];
            cnt[a + b] ++;
        } else {
            ans -= cnt[a - n + b];
            cnt[a - n + b] ++;
        }
    }
    cout << ans << endl;
    return 0;
}
